// ─── State Manager ───────────────────────────────────────
export class GameStateManager {
  state: GameState = 'title';
  mode: GameMode = 'classic';
  difficulty: Difficulty = 'medium';
  machineIndex: number = 0;
  themeIndex: number = 0;

  // Game session
  score: number = 0;
  grabs: number = 0;
  misses: number = 0;
  attempts: number = 0;
  maxAttempts: number = 5;
  streak: number = 0;
  bestStreak: number = 0;
  combo: number = 1;
  comboTimer: number = 0;
  timeRemaining: number = 0;
  progressiveRound: number = 1;
  targetPrizeId: string = '';
  targetHits: number = 0;
  targetTotal: number = 3;
  ticketsEarned: number = 0;
  grabStartTime: number = 0;

  // Claw
  clawPhase: ClawPhase = 'idle';
  clawX: number = 0;
  clawZ: number = 0;
  clawY: number = 0;
  clawTargetY: number = 0;
  clawGripping: boolean = false;
  grabbedPrize: any = null;

  // Persistence
  achievements: Achievement[] = getDefaultAchievements();
  leaderboard: any[] = [];
  collection: Set<string> = new Set();
  totalGrabs: number = 0;
  totalMisses: number = 0;
  totalScore: number = 0;
  totalTickets: number = 0;
  totalGames: number = 0;
  bestScore: number = 0;
  bestStreak_career: number = 0;
  themesUsed: Set<string> = new Set();
  machinesUsed: Set<string> = new Set();

  constructor() { this.load(); }

  get machine(): MachineConfig { return MACHINES[this.machineIndex]; }
  get theme(): ArenaTheme { return THEMES[this.themeIndex]; }

  save(): void {
    try {
      localStorage.setItem('neon-claw-achievements', JSON.stringify(this.achievements));
      localStorage.setItem('neon-claw-leaderboard', JSON.stringify(this.leaderboard));
      localStorage.setItem('neon-claw-collection', JSON.stringify([...this.collection]));
      localStorage.setItem('neon-claw-stats', JSON.stringify({
        totalGrabs: this.totalGrabs, totalMisses: this.totalMisses, totalScore: this.totalScore,
        totalTickets: this.totalTickets, totalGames: this.totalGames, bestScore: this.bestScore,
        bestStreak: this.bestStreak_career, themeIndex: this.themeIndex,
        themesUsed: [...this.themesUsed], machinesUsed: [...this.machinesUsed],
      }));
    } catch {}
  }

  load(): void {
    try {
      const a = localStorage.getItem('neon-claw-achievements');
      if (a) {
        const saved = JSON.parse(a) as Achievement[];
        const defaults = getDefaultAchievements();
        this.achievements = defaults.map(d => {
          const s = saved.find(x => x.id === d.id);
          return s ? { ...d, unlocked: s.unlocked } : d;
        });
      }
      const lb = localStorage.getItem('neon-claw-leaderboard');
      if (lb) this.leaderboard = JSON.parse(lb);
      const c = localStorage.getItem('neon-claw-collection');
      if (c) this.collection = new Set(JSON.parse(c));
      const st = localStorage.getItem('neon-claw-stats');
      if (st) {
        const s = JSON.parse(st);
        this.totalGrabs = s.totalGrabs || 0;
        this.totalMisses = s.totalMisses || 0;
        this.totalScore = s.totalScore || 0;
        this.totalTickets = s.totalTickets || 0;
        this.totalGames = s.totalGames || 0;
        this.bestScore = s.bestScore || 0;
        this.bestStreak_career = s.bestStreak || 0;
        this.themeIndex = s.themeIndex || 0;
        this.themesUsed = new Set(s.themesUsed || []);
        this.machinesUsed = new Set(s.machinesUsed || []);
      }
    } catch {}
  }

  resetSession(): void {
    this.score = 0; this.grabs = 0; this.misses = 0; this.attempts = 0;
    this.streak = 0; this.bestStreak = 0; this.combo = 1; this.comboTimer = 0;
    this.ticketsEarned = 0; this.progressiveRound = 1;
    this.targetHits = 0; this.clawPhase = 'idle'; this.grabbedPrize = null;
  }

  addToLeaderboard(entry: any): void {
    this.leaderboard.push(entry);
    this.leaderboard.sort((a: any, b: any) => b.score - a.score);
    if (this.leaderboard.length > 20) this.leaderboard = this.leaderboard.slice(0, 20);
    this.save();
  }

  unlockAchievement(id: string): boolean {
    const a = this.achievements.find(x => x.id === id);
    if (a && !a.unlocked) { a.unlocked = true; this.save(); return true; }
    return false;
  }
}

// ─── Seeded RNG for Daily Challenges ─────────────────────
export function seededRandom(seed: number): () => number {
  let s = seed;
  return () => { s = (s * 1664525 + 1013904223) & 0xffffffff; return (s >>> 0) / 0xffffffff; };
}

export function getDailySeed(): number {
  const d = new Date();
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}

// machine.ts — Claw machine geometry, prizes, claw mechanics
import {
  Mesh, Group, BoxGeometry, SphereGeometry, CylinderGeometry, ConeGeometry,
  OctahedronGeometry, TorusGeometry, CapsuleGeometry,
  MeshStandardMaterial, MeshBasicMaterial, LineBasicMaterial,
  EdgesGeometry, LineSegments, AdditiveBlending,
  Color, Vector3,
} from '@iwsdk/core';
import { MachineConfig, PrizeType, PRIZE_TYPES, RARITY_COLORS, ArenaTheme } from './types';

// ─── Prize Mesh Creation ─────────────────────────────────
export function createPrizeMesh(prize: PrizeType): Group {
  const group = new Group();
  const color = new Color(prize.baseColor);
  const emissive = new Color(prize.emissiveColor);
  const s = prize.size * 0.06;
  let geom: any;
  switch (prize.shape) {
    case 'cube': geom = new BoxGeometry(s, s, s); break;
    case 'sphere': geom = new SphereGeometry(s * 0.55, 12, 8); break;
    case 'cylinder': geom = new CylinderGeometry(s * 0.35, s * 0.35, s * 0.9, 10); break;
    case 'diamond': geom = new OctahedronGeometry(s * 0.5, 0); break;
    case 'star': geom = createStarGeometry(s * 0.5); break;
    case 'capsule': geom = new CapsuleGeometry(s * 0.3, s * 0.5, 6, 10); break;
  }
  const mat = new MeshStandardMaterial({ color, emissive, emissiveIntensity: 0.6, metalness: 0.4, roughness: 0.3 });
  const mesh = new Mesh(geom, mat);
  group.add(mesh);

  // Wireframe edges
  const edges = new EdgesGeometry(geom);
  const lineMat = new LineBasicMaterial({ color: prize.baseColor, transparent: true, opacity: 0.4 });
  group.add(new LineSegments(edges, lineMat));

  // Glow sphere
  const glowMat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.15, blending: AdditiveBlending });
  const glowMesh = new Mesh(new SphereGeometry(s * 0.8, 8, 6), glowMat);
  group.add(glowMesh);

  (group as any)._prizeData = prize;
  (group as any)._velocity = new Vector3(0, 0, 0);
  (group as any)._grounded = false;
  return group;
}

function createStarGeometry(r: number): ConeGeometry {
  // Use a cone as star stand-in with more points
  return new ConeGeometry(r, r * 1.5, 5);
}

// ─── Claw Mesh ───────────────────────────────────────────
export function createClawGroup(theme: ArenaTheme): Group {
  const claw = new Group();
  const clawColor = new Color(theme.claw);

  // Central hub
  const hubGeo = new CylinderGeometry(0.03, 0.03, 0.06, 8);
  const hubMat = new MeshStandardMaterial({ color: clawColor, emissive: clawColor, emissiveIntensity: 0.5, metalness: 0.8 });
  const hub = new Mesh(hubGeo, hubMat);
  claw.add(hub);

  // Cable (extends upward)
  const cableGeo = new CylinderGeometry(0.005, 0.005, 0.5, 4);
  const cableMat = new MeshStandardMaterial({ color: clawColor, emissive: clawColor, emissiveIntensity: 0.3 });
  const cable = new Mesh(cableGeo, cableMat);
  cable.position.y = 0.28;
  claw.add(cable);

  // 3 prongs
  for (let i = 0; i < 3; i++) {
    const angle = (i / 3) * Math.PI * 2;
    const prong = createClawProng(clawColor);
    prong.position.set(Math.cos(angle) * 0.025, -0.03, Math.sin(angle) * 0.025);
    prong.rotation.z = -0.4; // partially open
    prong.rotation.y = -angle;
    prong.name = `prong_${i}`;
    claw.add(prong);
  }

  // Glow ring around hub
  const ringGeo = new TorusGeometry(0.04, 0.005, 6, 16);
  const ringMat = new MeshBasicMaterial({ color: clawColor, transparent: true, opacity: 0.4, blending: AdditiveBlending });
  const ring = new Mesh(ringGeo, ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 0.005;
  ring.name = 'glow_ring';
  claw.add(ring);

  return claw;
}

function createClawProng(color: Color): Group {
  const prong = new Group();
  const mat = new MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.4, metalness: 0.7 });

  // Upper arm
  const upper = new Mesh(new BoxGeometry(0.008, 0.06, 0.008), mat);
  upper.position.y = -0.03;
  prong.add(upper);

  // Lower arm (curved inward tip)
  const lower = new Mesh(new BoxGeometry(0.008, 0.04, 0.008), mat);
  lower.position.set(0.01, -0.075, 0);
  lower.rotation.z = 0.3;
  prong.add(lower);

  // Tip
  const tip = new Mesh(new SphereGeometry(0.006, 6, 4), mat);
  tip.position.set(0.015, -0.092, 0);
  prong.add(tip);

  return prong;
}

// ─── Machine Glass Box ───────────────────────────────────
export function createMachineBox(config: MachineConfig, theme: ArenaTheme): Group {
  const box = new Group();
  const w = config.pitWidth;
  const d = config.pitDepth;
  const h = config.pitHeight;
  const glassColor = new Color(theme.glass);
  const machineColor = new Color(theme.machine);

  // Floor
  const floorGeo = new BoxGeometry(w, 0.02, d);
  const floorMat = new MeshStandardMaterial({ color: machineColor, emissive: new Color(theme.glow), emissiveIntensity: 0.2, metalness: 0.5 });
  const floor = new Mesh(floorGeo, floorMat);
  floor.position.y = -h / 2;
  box.add(floor);

  // Floor grid lines
  const gridMat = new LineBasicMaterial({ color: theme.grid, transparent: true, opacity: 0.25 });
  for (let i = -5; i <= 5; i++) {
    const frac = i / 5;
    // X lines
    const xPts = [new Vector3(frac * w / 2, -h / 2 + 0.011, -d / 2), new Vector3(frac * w / 2, -h / 2 + 0.011, d / 2)];
    const xLine = new LineSegments(new EdgesGeometry(new BoxGeometry(0.001, 0.001, d)), gridMat);
    xLine.position.set(frac * w / 2, -h / 2 + 0.011, 0);
    box.add(xLine);
    // Z lines
    const zLine = new LineSegments(new EdgesGeometry(new BoxGeometry(w, 0.001, 0.001)), gridMat);
    zLine.position.set(0, -h / 2 + 0.011, frac * d / 2);
    box.add(zLine);
  }

  // Glass walls (transparent)
  const glassMat = new MeshStandardMaterial({
    color: glassColor, transparent: true, opacity: 0.08, metalness: 0.1, roughness: 0.1,
  });
  const glassEdgeMat = new LineBasicMaterial({ color: theme.glass, transparent: true, opacity: 0.3 });

  // Front wall
  const frontGeo = new BoxGeometry(w, h, 0.005);
  const front = new Mesh(frontGeo, glassMat);
  front.position.set(0, 0, d / 2);
  box.add(front);
  box.add(createEdges(frontGeo, glassEdgeMat, 0, 0, d / 2));

  // Back wall
  const back = new Mesh(frontGeo, glassMat);
  back.position.set(0, 0, -d / 2);
  box.add(back);
  box.add(createEdges(frontGeo, glassEdgeMat, 0, 0, -d / 2));

  // Left wall
  const sideGeo = new BoxGeometry(0.005, h, d);
  const left = new Mesh(sideGeo, glassMat);
  left.position.set(-w / 2, 0, 0);
  box.add(left);
  box.add(createEdges(sideGeo, glassEdgeMat, -w / 2, 0, 0));

  // Right wall
  const right = new Mesh(sideGeo, glassMat);
  right.position.set(w / 2, 0, 0);
  box.add(right);
  box.add(createEdges(sideGeo, glassEdgeMat, w / 2, 0, 0));

  // Top rail frame
  const railThickness = 0.02;
  const railMat = new MeshStandardMaterial({ color: glassColor, emissive: glassColor, emissiveIntensity: 0.3, metalness: 0.6 });
  // Front rail
  box.add(createRail(w + railThickness * 2, railThickness, railThickness, 0, h / 2, d / 2, railMat));
  // Back rail
  box.add(createRail(w + railThickness * 2, railThickness, railThickness, 0, h / 2, -d / 2, railMat));
  // Left rail
  box.add(createRail(railThickness, railThickness, d, -w / 2, h / 2, 0, railMat));
  // Right rail
  box.add(createRail(railThickness, railThickness, d, w / 2, h / 2, 0, railMat));

  // Drop chute (front-right corner)
  const chuteW = 0.15;
  const chuteD = 0.15;
  const chuteMat = new MeshStandardMaterial({ color: new Color(theme.accent), emissive: new Color(theme.accent), emissiveIntensity: 0.4, metalness: 0.5 });
  const chute = new Mesh(new BoxGeometry(chuteW, h * 0.6, chuteD), new MeshStandardMaterial({ color: new Color(theme.accent), transparent: true, opacity: 0.15 }));
  chute.position.set(w / 2 + chuteW / 2 + 0.02, -h * 0.2, d / 2 - chuteD / 2);
  box.add(chute);

  // Chute label ring
  const chuteRing = new Mesh(new TorusGeometry(0.06, 0.005, 6, 12), new MeshBasicMaterial({ color: theme.accent, transparent: true, opacity: 0.5, blending: AdditiveBlending }));
  chuteRing.position.set(w / 2 + chuteW / 2 + 0.02, h * 0.1, d / 2 - chuteD / 2);
  chuteRing.rotation.x = Math.PI / 2;
  chuteRing.name = 'chute_ring';
  box.add(chuteRing);

  // Corner accent lights
  const accentPositions = [
    [-w / 2, h / 2, d / 2], [w / 2, h / 2, d / 2],
    [-w / 2, h / 2, -d / 2], [w / 2, h / 2, -d / 2],
  ];
  accentPositions.forEach(([x, y, z]) => {
    const light = new Mesh(new SphereGeometry(0.01, 6, 4), new MeshBasicMaterial({ color: theme.accent, blending: AdditiveBlending }));
    light.position.set(x, y, z);
    box.add(light);
  });

  return box;
}

function createEdges(geo: any, mat: LineBasicMaterial, x: number, y: number, z: number): LineSegments {
  const edges = new LineSegments(new EdgesGeometry(geo), mat);
  edges.position.set(x, y, z);
  return edges;
}

function createRail(w: number, h: number, d: number, x: number, y: number, z: number, mat: MeshStandardMaterial): Mesh {
  const rail = new Mesh(new BoxGeometry(w, h, d), mat);
  rail.position.set(x, y, z);
  return rail;
}

// ─── Prize Spawning ──────────────────────────────────────
export function spawnPrizes(config: MachineConfig, rng?: () => number): { group: Group; prizes: Group[] } {
  const parent = new Group();
  const prizes: Group[] = [];
  const rand = rng || Math.random;
  const w = config.pitWidth * 0.8;
  const d = config.pitDepth * 0.8;

  for (let i = 0; i < config.prizeCount; i++) {
    const typeId = config.prizePool[Math.floor(rand() * config.prizePool.length)];
    const prizeType = PRIZE_TYPES.find(p => p.id === typeId)!;
    const mesh = createPrizeMesh(prizeType);

    // Random position within pit
    mesh.position.set(
      (rand() - 0.5) * w,
      -config.pitHeight / 2 + 0.04 + rand() * 0.02,
      (rand() - 0.5) * d,
    );
    mesh.rotation.set(rand() * Math.PI, rand() * Math.PI, rand() * Math.PI);

    parent.add(mesh);
    prizes.push(mesh);
  }

  return { group: parent, prizes };
}

// ─── Claw Rail System ────────────────────────────────────
export function createClawRail(config: MachineConfig, theme: ArenaTheme): Group {
  const rail = new Group();
  const railColor = new Color(theme.claw);
  const mat = new MeshStandardMaterial({ color: railColor, emissive: railColor, emissiveIntensity: 0.3, metalness: 0.7 });
  const w = config.pitWidth;
  const d = config.pitDepth;
  const topY = config.pitHeight / 2 + 0.12;

  // X-axis rails (front and back)
  const xRailGeo = new CylinderGeometry(0.008, 0.008, w + 0.1, 6);
  xRailGeo.rotateZ(Math.PI / 2);
  const xFront = new Mesh(xRailGeo, mat);
  xFront.position.set(0, topY, d / 2 + 0.03);
  rail.add(xFront);
  const xBack = new Mesh(xRailGeo, mat);
  xBack.position.set(0, topY, -d / 2 - 0.03);
  rail.add(xBack);

  // Z-axis rail (movable carriage rail)
  const zRailGeo = new CylinderGeometry(0.008, 0.008, d + 0.1, 6);
  const zRail = new Mesh(zRailGeo, mat);
  zRail.rotation.x = Math.PI / 2;
  zRail.position.y = topY;
  zRail.name = 'z_rail';
  rail.add(zRail);

  // Carriage block
  const carriage = new Mesh(new BoxGeometry(0.04, 0.02, 0.04), mat);
  carriage.position.y = topY - 0.01;
  carriage.name = 'carriage';
  rail.add(carriage);

  return rail;
}

// audio.ts — Procedural Web Audio for Neon Claw VR

export class AudioManager {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private sfxGain: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private droneOsc1: OscillatorNode | null = null;
  private droneOsc2: OscillatorNode | null = null;
  private droneLFO: OscillatorNode | null = null;

  private masterVol = 0.7;
  private sfxVol = 0.8;
  private musicVol = 0.3;

  init(): void {
    if (this.ctx) return;
    this.ctx = new AudioContext();
    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = this.masterVol;
    this.masterGain.connect(this.ctx.destination);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = this.sfxVol;
    this.sfxGain.connect(this.masterGain);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = this.musicVol;
    this.musicGain.connect(this.masterGain);

    this.startDrone();
  }

  private startDrone(): void {
    if (!this.ctx || !this.musicGain) return;
    const t = this.ctx.currentTime;

    // Sub bass drone
    this.droneOsc1 = this.ctx.createOscillator();
    this.droneOsc1.type = 'sine';
    this.droneOsc1.frequency.value = 55;
    const g1 = this.ctx.createGain();
    g1.gain.value = 0.15;
    this.droneOsc1.connect(g1);
    g1.connect(this.musicGain);
    this.droneOsc1.start(t);

    // Pad layer
    this.droneOsc2 = this.ctx.createOscillator();
    this.droneOsc2.type = 'triangle';
    this.droneOsc2.frequency.value = 82.5;
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 400;
    const g2 = this.ctx.createGain();
    g2.gain.value = 0.08;
    this.droneOsc2.connect(lp);
    lp.connect(g2);
    g2.connect(this.musicGain);
    this.droneOsc2.start(t);

    // LFO modulation
    this.droneLFO = this.ctx.createOscillator();
    this.droneLFO.type = 'sine';
    this.droneLFO.frequency.value = 0.15;
    const lfoG = this.ctx.createGain();
    lfoG.gain.value = 3;
    this.droneLFO.connect(lfoG);
    lfoG.connect(this.droneOsc1.frequency);
    this.droneLFO.start(t);
  }

  private playTone(freq: number, type: OscillatorType, dur: number, vol: number, node?: GainNode): void {
    if (!this.ctx) return;
    const dest = node || this.sfxGain;
    if (!dest) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g);
    g.connect(dest);
    o.start(t);
    o.stop(t + dur);
  }

  private playNoise(dur: number, vol: number, filterFreq?: number): void {
    if (!this.ctx || !this.sfxGain) return;
    const t = this.ctx.currentTime;
    const bufSize = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < bufSize; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    if (filterFreq) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filterFreq;
      src.connect(f);
      f.connect(g);
    } else {
      src.connect(g);
    }
    g.connect(this.sfxGain);
    src.start(t);
  }

  // ─── SFX Methods ─────────────────────────────────────
  clawMove(): void {
    this.playTone(220, 'square', 0.05, 0.06);
  }

  clawDrop(): void {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(800, t);
    o.frequency.exponentialRampToValueAtTime(200, t + 0.4);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.12, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
    o.connect(g);
    g.connect(this.sfxGain!);
    o.start(t);
    o.stop(t + 0.4);
  }

  clawClose(): void {
    this.playTone(440, 'square', 0.15, 0.1);
    this.playNoise(0.1, 0.08, 2000);
  }

  clawGrab(): void {
    // Success: ascending arpeggio
    if (!this.ctx) return;
    const notes = [523, 659, 784, 1047];
    notes.forEach((f, i) => {
      setTimeout(() => this.playTone(f, 'sine', 0.2, 0.12), i * 80);
    });
  }

  clawMiss(): void {
    // Failure: descending tones
    if (!this.ctx) return;
    this.playTone(400, 'sawtooth', 0.3, 0.08);
    setTimeout(() => this.playTone(300, 'sawtooth', 0.3, 0.06), 100);
    setTimeout(() => this.playTone(200, 'sawtooth', 0.4, 0.04), 200);
  }

  prizeCollect(): void {
    if (!this.ctx) return;
    const notes = [659, 784, 988, 1175, 1319];
    notes.forEach((f, i) => {
      setTimeout(() => this.playTone(f, 'sine', 0.15, 0.1), i * 60);
    });
    this.playNoise(0.2, 0.05, 3000);
  }

  buttonClick(): void {
    this.playTone(880, 'sine', 0.05, 0.1);
    this.playTone(1100, 'sine', 0.04, 0.06);
  }

  gameStart(): void {
    if (!this.ctx) return;
    [440, 554, 659, 880].forEach((f, i) => {
      setTimeout(() => this.playTone(f, 'triangle', 0.2, 0.1), i * 100);
    });
  }

  gameOver(): void {
    if (!this.ctx) return;
    [660, 554, 440, 330].forEach((f, i) => {
      setTimeout(() => this.playTone(f, 'triangle', 0.3, 0.08), i * 150);
    });
  }

  achievementUnlock(): void {
    if (!this.ctx) return;
    [523, 659, 784, 988, 1175].forEach((f, i) => {
      setTimeout(() => this.playTone(f, 'sine', 0.25, 0.1), i * 80);
    });
  }

  countdownTick(): void {
    this.playTone(660, 'sine', 0.08, 0.12);
  }

  countdownGo(): void {
    this.playTone(1320, 'sine', 0.3, 0.15);
  }

  comboUp(): void {
    this.playTone(880, 'triangle', 0.15, 0.1);
    this.playTone(1100, 'triangle', 0.1, 0.08);
  }

  clawAscend(): void {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(200, t);
    o.frequency.exponentialRampToValueAtTime(600, t + 0.3);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.08, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
    o.connect(g);
    g.connect(this.sfxGain!);
    o.start(t);
    o.stop(t + 0.3);
  }

  prizeRelease(): void {
    this.playTone(400, 'triangle', 0.2, 0.08);
    this.playNoise(0.15, 0.06, 1500);
  }

  setMasterVolume(v: number): void { this.masterVol = v; if (this.masterGain) this.masterGain.gain.value = v; }
  setSfxVolume(v: number): void { this.sfxVol = v; if (this.sfxGain) this.sfxGain.gain.value = v; }
  setMusicVolume(v: number): void { this.musicVol = v; if (this.musicGain) this.musicGain.gain.value = v; }
  getMasterVolume(): number { return this.masterVol; }
  getSfxVolume(): number { return this.sfxVol; }
  getMusicVolume(): number { return this.musicVol; }
}

// effects.ts — Particle effects, claw trail, screen shake
import {
  Mesh, Group, SphereGeometry, MeshBasicMaterial, AdditiveBlending, Color, Vector3,
} from '@iwsdk/core';

// ─── Particle System ─────────────────────────────────────
interface Particle {
  mesh: Mesh;
  vel: Vector3;
  life: number;
  maxLife: number;
}

export class ParticleSystem {
  private particles: Particle[] = [];
  private pool: Particle[] = [];
  private parent: Group;
  private maxParticles = 100;

  constructor(parent: Group) {
    this.parent = parent;
    for (let i = 0; i < this.maxParticles; i++) {
      const mesh = new Mesh(
        new SphereGeometry(0.008, 4, 3),
        new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, blending: AdditiveBlending }),
      );
      mesh.visible = false;
      parent.add(mesh);
      this.pool.push({ mesh, vel: new Vector3(), life: 0, maxLife: 0 });
    }
  }

  burst(pos: Vector3, color: string, count: number, speed: number = 1.5, life: number = 0.8): void {
    const c = new Color(color);
    for (let i = 0; i < count; i++) {
      const p = this.pool.pop();
      if (!p) break;
      p.mesh.position.copy(pos);
      (p.mesh.material as MeshBasicMaterial).color.copy(c);
      (p.mesh.material as MeshBasicMaterial).opacity = 0.8;
      p.mesh.visible = true;
      p.vel.set(
        (Math.random() - 0.5) * speed,
        Math.random() * speed * 0.8 + speed * 0.3,
        (Math.random() - 0.5) * speed,
      );
      p.life = life;
      p.maxLife = life;
      this.particles.push(p);
    }
  }

  update(dt: number): void {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        p.mesh.visible = false;
        this.pool.push(p);
        this.particles.splice(i, 1);
        continue;
      }
      p.vel.y -= 2.5 * dt; // gravity
      p.mesh.position.addScaledVector(p.vel, dt);
      const frac = p.life / p.maxLife;
      (p.mesh.material as MeshBasicMaterial).opacity = frac * 0.8;
      p.mesh.scale.setScalar(0.5 + frac * 0.5);
    }
  }
}

// ─── Claw Position Indicator ─────────────────────────────
export function createClawShadow(): Mesh {
  const geo = new SphereGeometry(0.03, 8, 4);
  geo.scale(1, 0.1, 1);
  const mat = new MeshBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.3, blending: AdditiveBlending });
  const shadow = new Mesh(geo, mat);
  shadow.visible = false;
  return shadow;
}

export function updateClawShadow(shadow: Mesh, clawX: number, clawZ: number, floorY: number, active: boolean, time: number): void {
  shadow.visible = active;
  if (!active) return;
  shadow.position.set(clawX, floorY + 0.01, clawZ);
  const pulse = 0.8 + 0.2 * Math.sin(time * 4);
  shadow.scale.set(pulse, 0.1, pulse);
  (shadow.material as MeshBasicMaterial).opacity = 0.2 + 0.1 * Math.sin(time * 3);
}

// ─── Screen Shake (Browser only) ─────────────────────────
export class ScreenShake {
  intensity = 0;
  duration = 0;
  elapsed = 0;
  offset = new Vector3();

  trigger(intensity: number, duration: number): void {
    this.intensity = intensity;
    this.duration = duration;
    this.elapsed = 0;
  }

  update(dt: number): Vector3 {
    if (this.elapsed >= this.duration) {
      this.offset.set(0, 0, 0);
      return this.offset;
    }
    this.elapsed += dt;
    const decay = 1 - this.elapsed / this.duration;
    const i = this.intensity * decay;
    this.offset.set(
      (Math.random() - 0.5) * i * 2,
      (Math.random() - 0.5) * i * 2,
      (Math.random() - 0.5) * i * 0.5,
    );
    return this.offset;
  }
}

// environment.ts — Holodeck environment, lighting, particles, decorations
import {
  Mesh, Group, BoxGeometry, SphereGeometry, TorusGeometry, ConeGeometry,
  MeshBasicMaterial, MeshStandardMaterial, LineBasicMaterial,
  EdgesGeometry, LineSegments, AdditiveBlending,
  Color, Vector3, AmbientLight, PointLight, Fog,
} from '@iwsdk/core';
import { ArenaTheme } from './types';

export interface EnvironmentObjects {
  group: Group;
  decorations: Mesh[];
  particles: Mesh[];
  lights: PointLight[];
}

export function createEnvironment(theme: ArenaTheme): EnvironmentObjects {
  const group = new Group();
  const decorations: Mesh[] = [];
  const particles: Mesh[] = [];
  const lights: PointLight[] = [];
  const gridColor = new Color(theme.grid);
  const accentColor = new Color(theme.accent);

  // ─── Neon Grid Floor ─────────────────────────────────
  const gridSize = 20;
  const gridMat = new LineBasicMaterial({ color: gridColor, transparent: true, opacity: 0.2 });
  for (let i = -gridSize; i <= gridSize; i++) {
    // X lines
    const xGeo = new BoxGeometry(gridSize * 2, 0.001, 0.001);
    const xLine = new LineSegments(new EdgesGeometry(xGeo), gridMat);
    xLine.position.set(0, 0, i);
    group.add(xLine);
    // Z lines
    const zGeo = new BoxGeometry(0.001, 0.001, gridSize * 2);
    const zLine = new LineSegments(new EdgesGeometry(zGeo), gridMat);
    zLine.position.set(i, 0, 0);
    group.add(zLine);
  }

  // Ceiling grid
  const ceilY = 5;
  const ceilMat = new LineBasicMaterial({ color: gridColor, transparent: true, opacity: 0.08 });
  for (let i = -gridSize; i <= gridSize; i += 2) {
    const xLine = new LineSegments(new EdgesGeometry(new BoxGeometry(gridSize * 2, 0.001, 0.001)), ceilMat);
    xLine.position.set(0, ceilY, i);
    group.add(xLine);
    const zLine = new LineSegments(new EdgesGeometry(new BoxGeometry(0.001, 0.001, gridSize * 2)), ceilMat);
    zLine.position.set(i, ceilY, 0);
    group.add(zLine);
  }

  // ─── Floating Wireframe Decorations ──────────────────
  const decoShapes = [
    () => new TorusGeometry(0.3, 0.08, 8, 16),
    () => new BoxGeometry(0.4, 0.4, 0.4),
    () => new SphereGeometry(0.25, 8, 6),
    () => new ConeGeometry(0.2, 0.5, 6),
  ];

  for (let i = 0; i < 14; i++) {
    const geo = decoShapes[i % decoShapes.length]();
    const edgesGeo = new EdgesGeometry(geo);
    const color = i % 2 === 0 ? gridColor : accentColor;
    const lineMat = new LineBasicMaterial({ color, transparent: true, opacity: 0.15 });
    const deco = new LineSegments(edgesGeo, lineMat) as any;
    const angle = (i / 14) * Math.PI * 2;
    const radius = 4 + Math.random() * 4;
    deco.position.set(
      Math.cos(angle) * radius,
      1.5 + Math.random() * 2.5,
      Math.sin(angle) * radius,
    );
    deco._baseY = deco.position.y;
    deco._rotSpeed = 0.2 + Math.random() * 0.4;
    deco._bobSpeed = 0.3 + Math.random() * 0.3;
    deco._bobAmp = 0.1 + Math.random() * 0.15;
    group.add(deco);
    decorations.push(deco);
  }

  // ─── Ambient Particles ───────────────────────────────
  const particleMat = new MeshBasicMaterial({ color: gridColor, transparent: true, opacity: 0.3, blending: AdditiveBlending });
  for (let i = 0; i < 40; i++) {
    const p = new Mesh(new SphereGeometry(0.01, 4, 3), particleMat) as any;
    p.position.set(
      (Math.random() - 0.5) * 16,
      0.5 + Math.random() * 4,
      (Math.random() - 0.5) * 16,
    );
    p._baseY = p.position.y;
    p._driftX = (Math.random() - 0.5) * 0.02;
    p._driftZ = (Math.random() - 0.5) * 0.02;
    p._pulseSpeed = 1 + Math.random() * 2;
    p._pulsePhase = Math.random() * Math.PI * 2;
    group.add(p);
    particles.push(p);
  }

  // ─── Lighting ────────────────────────────────────────
  const ambient = new AmbientLight(0x111122, 0.4);
  group.add(ambient as any);

  const accent1 = new PointLight(new Color(theme.grid) as any, 1.5, 8);
  accent1.position.set(-2, 3, -2);
  group.add(accent1 as any);
  lights.push(accent1);

  const accent2 = new PointLight(new Color(theme.accent) as any, 1.2, 8);
  accent2.position.set(2, 3, 2);
  group.add(accent2 as any);
  lights.push(accent2);

  const machineLight = new PointLight(new Color(theme.claw) as any, 2.0, 5);
  machineLight.position.set(0, 2, 0);
  group.add(machineLight as any);
  lights.push(machineLight);

  return { group, decorations, particles, lights };
}

export function updateEnvironment(env: EnvironmentObjects, time: number): void {
  // Decorations rotate and bob
  for (const d of env.decorations) {
    const data = d as any;
    d.rotation.x += data._rotSpeed * 0.005;
    d.rotation.y += data._rotSpeed * 0.008;
    d.position.y = data._baseY + Math.sin(time * data._bobSpeed) * data._bobAmp;
  }

  // Particles drift and pulse
  for (const p of env.particles) {
    const data = p as any;
    p.position.x += data._driftX;
    p.position.z += data._driftZ;
    const opacity = 0.15 + 0.2 * Math.sin(time * data._pulseSpeed + data._pulsePhase);
    (p.material as MeshBasicMaterial).opacity = Math.max(0.05, opacity);

    // Wrap around
    if (Math.abs(p.position.x) > 8) data._driftX *= -1;
    if (Math.abs(p.position.z) > 8) data._driftZ *= -1;
  }
}

